library ieee;
    use ieee.std_logic_1164.all;

-- The Ethernet subsystem of tsemac_soc: Efinix's Triple Speed Ethernet MAC (efx_tsemac) on
-- the board's RGMII PHY, fed by the scatter-gather DMA (dma) between it and the SoC's DDR
-- master port, both generated by gen_ips.py.
--
--   receive    MAC -> DMA channel 0 (its own clock: the PHY's receive clock) -> memory
--   transmit   memory -> DMA channel 1 -> tx_checksum_inserter -> MAC; the inserter stores
--              each frame whole and plays it out a byte a clock, so the MAC gets no gaps
--   registers  the DMA's on dma_apb; on eth_apb the MAC's (its AXI4-Lite through the
--              apb3_2_axi4_lite bridge) at 0x000..0x1ff and tsemac_control's resets at
--              0x200..0x3ff (the drivers' MAC base + 0x200)
--
-- Resets: the MAC's own, and the DMA channels' and the inserter's, follow the clocks' PLL lock
-- (pll_locked low: all of them); the software resets of tsemac_control add to them. A reset
-- into the MAC's or the inserter's clock domain is asserted at once and released two clocks
-- after its source.
entity ethernet_subsystem is
    generic(g_axi_width : natural := 64);
    port(
        io_systemReset        : in  std_logic;
        io_ddrMasterReset     : in  std_logic;
        io_peripheralClk      : in  std_logic;
        io_memoryClk          : in  std_logic;
        io_tseClk             : in  std_logic;
        pll_locked            : in  std_logic;

        rgmii_txd_HI          : out std_logic_vector(3 downto 0);
        rgmii_txd_LO          : out std_logic_vector(3 downto 0);
        rgmii_tx_ctl_HI       : out std_logic;
        rgmii_tx_ctl_LO       : out std_logic;
        rgmii_txc_HI          : out std_logic;
        rgmii_txc_LO          : out std_logic;
        rgmii_rxd_HI          : in  std_logic_vector(3 downto 0);
        rgmii_rxd_LO          : in  std_logic_vector(3 downto 0);
        rgmii_rx_ctl_HI       : in  std_logic;
        rgmii_rx_ctl_LO       : in  std_logic;
        rgmii_rxc             : in  std_logic;
        phy_mdi               : in  std_logic;
        phy_mdo               : out std_logic;
        phy_mdo_en            : out std_logic;
        phy_mdc               : out std_logic;
        phy_sw_rst            : out std_logic;
        dma_interrupts        : out std_logic_vector(1 downto 0);
        eth_speed             : out std_logic_vector(2 downto 0);

        eth_apb3_paddr        : in  std_logic_vector(31 downto 0);
        eth_apb3_psel         : in  std_logic;
        eth_apb3_penable      : in  std_logic;
        eth_apb3_pwrite       : in  std_logic;
        eth_apb3_pwdata       : in  std_logic_vector(31 downto 0);
        eth_apb3_pready       : out std_logic;
        eth_apb3_prdata       : out std_logic_vector(31 downto 0);
        eth_apb3_pslverror    : out std_logic;
        dma_apb3_paddr        : in  std_logic_vector(31 downto 0);
        dma_apb3_psel         : in  std_logic;
        dma_apb3_penable      : in  std_logic;
        dma_apb3_pwrite       : in  std_logic;
        dma_apb3_pwdata       : in  std_logic_vector(31 downto 0);
        dma_apb3_pready       : out std_logic;
        dma_apb3_prdata       : out std_logic_vector(31 downto 0);
        dma_apb3_pslverror    : out std_logic;

        dmaaxi_read_arvalid   : out std_logic;
        dmaaxi_read_arready   : in  std_logic;
        dmaaxi_read_araddr    : out std_logic_vector(31 downto 0);
        dmaaxi_read_arregion  : out std_logic_vector(3 downto 0);
        dmaaxi_read_arlen     : out std_logic_vector(7 downto 0);
        dmaaxi_read_arsize    : out std_logic_vector(2 downto 0);
        dmaaxi_read_arburst   : out std_logic_vector(1 downto 0);
        dmaaxi_read_arlock    : out std_logic_vector(0 downto 0);
        dmaaxi_read_arcache   : out std_logic_vector(3 downto 0);
        dmaaxi_read_arqos     : out std_logic_vector(3 downto 0);
        dmaaxi_read_arprot    : out std_logic_vector(2 downto 0);
        dmaaxi_read_rvalid    : in  std_logic;
        dmaaxi_read_rready    : out std_logic;
        dmaaxi_read_rdata     : in  std_logic_vector(g_axi_width-1 downto 0);
        dmaaxi_read_rresp     : in  std_logic_vector(1 downto 0);
        dmaaxi_read_rlast     : in  std_logic;
        dmaaxi_write_awvalid  : out std_logic;
        dmaaxi_write_awready  : in  std_logic;
        dmaaxi_write_awaddr   : out std_logic_vector(31 downto 0);
        dmaaxi_write_awregion : out std_logic_vector(3 downto 0);
        dmaaxi_write_awlen    : out std_logic_vector(7 downto 0);
        dmaaxi_write_awsize   : out std_logic_vector(2 downto 0);
        dmaaxi_write_awburst  : out std_logic_vector(1 downto 0);
        dmaaxi_write_awlock   : out std_logic_vector(0 downto 0);
        dmaaxi_write_awcache  : out std_logic_vector(3 downto 0);
        dmaaxi_write_awqos    : out std_logic_vector(3 downto 0);
        dmaaxi_write_awprot   : out std_logic_vector(2 downto 0);
        dmaaxi_write_wvalid   : out std_logic;
        dmaaxi_write_wready   : in  std_logic;
        dmaaxi_write_wdata    : out std_logic_vector(g_axi_width-1 downto 0);
        dmaaxi_write_wstrb    : out std_logic_vector(g_axi_width/8-1 downto 0);
        dmaaxi_write_wlast    : out std_logic;
        dmaaxi_write_bvalid   : in  std_logic;
        dmaaxi_write_bready   : out std_logic;
        dmaaxi_write_bresp    : in  std_logic_vector(1 downto 0)
    );
end entity ethernet_subsystem;

architecture rtl of ethernet_subsystem is

    -- the generated IPs (ip/*/: gen_ips.py), their ports as in their Verilog
    component dma is
    port(
        clk            : in  std_logic;
        reset          : in  std_logic;
        ctrl_clk       : in  std_logic;
        ctrl_reset     : in  std_logic;
        ctrl_PADDR     : in  std_logic_vector(13 downto 0);
        ctrl_PREADY    : out std_logic;
        ctrl_PENABLE   : in  std_logic;
        ctrl_PSEL      : in  std_logic;
        ctrl_PWRITE    : in  std_logic;
        ctrl_PWDATA    : in  std_logic_vector(31 downto 0);
        ctrl_PRDATA    : out std_logic_vector(31 downto 0);
        ctrl_PSLVERROR : out std_logic;
        ctrl_interrupts : out std_logic_vector(1 downto 0);
        read_arvalid   : out std_logic;
        read_araddr    : out std_logic_vector(31 downto 0);
        read_arready   : in  std_logic;
        read_arregion  : out std_logic_vector(3 downto 0);
        read_arlen     : out std_logic_vector(7 downto 0);
        read_arsize    : out std_logic_vector(2 downto 0);
        read_arburst   : out std_logic_vector(1 downto 0);
        read_arlock    : out std_logic;
        read_arcache   : out std_logic_vector(3 downto 0);
        read_arqos     : out std_logic_vector(3 downto 0);
        read_arprot    : out std_logic_vector(2 downto 0);
        read_rready    : out std_logic;
        read_rvalid    : in  std_logic;
        read_rdata     : in  std_logic_vector(63 downto 0);
        read_rlast     : in  std_logic;
        read_rresp     : in  std_logic_vector(1 downto 0);
        write_awvalid  : out std_logic;
        write_awready  : in  std_logic;
        write_awaddr   : out std_logic_vector(31 downto 0);
        write_awregion : out std_logic_vector(3 downto 0);
        write_awlen    : out std_logic_vector(7 downto 0);
        write_awsize   : out std_logic_vector(2 downto 0);
        write_awburst  : out std_logic_vector(1 downto 0);
        write_awlock   : out std_logic;
        write_awcache  : out std_logic_vector(3 downto 0);
        write_awqos    : out std_logic_vector(3 downto 0);
        write_awprot   : out std_logic_vector(2 downto 0);
        write_wvalid   : out std_logic;
        write_wready   : in  std_logic;
        write_wdata    : out std_logic_vector(63 downto 0);
        write_wstrb    : out std_logic_vector(7 downto 0);
        write_wlast    : out std_logic;
        write_bvalid   : in  std_logic;
        write_bready   : out std_logic;
        write_bresp    : in  std_logic_vector(1 downto 0);
        io_0_descriptorUpdate : out std_logic;
        io_1_descriptorUpdate : out std_logic;
        dat0_i_clk     : in  std_logic;
        dat0_i_reset   : in  std_logic;
        dat0_i_tvalid  : in  std_logic;
        dat0_i_tready  : out std_logic;
        dat0_i_tdata   : in  std_logic_vector(7 downto 0);
        dat0_i_tkeep   : in  std_logic_vector(0 downto 0);
        dat0_i_tdest   : in  std_logic_vector(3 downto 0);
        dat0_i_tlast   : in  std_logic;
        dat1_o_clk     : in  std_logic;
        dat1_o_reset   : in  std_logic;
        dat1_o_tvalid  : out std_logic;
        dat1_o_tready  : in  std_logic;
        dat1_o_tdata   : out std_logic_vector(7 downto 0);
        dat1_o_tkeep   : out std_logic_vector(0 downto 0);
        dat1_o_tdest   : out std_logic_vector(3 downto 0);
        dat1_o_tlast   : out std_logic
    );
    end component dma;

    component efx_tsemac is
    port(
        mac_reset          : in  std_logic;
        proto_reset        : in  std_logic;
        tx_mac_aclk        : in  std_logic;
        rx_mac_aclk        : out std_logic;
        eth_speed          : out std_logic_vector(2 downto 0);
        rx_axis_clk        : in  std_logic;
        rx_axis_mac_tdata  : out std_logic_vector(7 downto 0);
        rx_axis_mac_tvalid : out std_logic;
        rx_axis_mac_tstrb  : out std_logic_vector(0 downto 0);
        rx_axis_mac_tlast  : out std_logic;
        rx_axis_mac_tuser  : out std_logic;
        rx_axis_mac_tready : in  std_logic;
        tx_axis_clk        : in  std_logic;
        tx_axis_mac_tdata  : in  std_logic_vector(7 downto 0);
        tx_axis_mac_tvalid : in  std_logic;
        tx_axis_mac_tstrb  : in  std_logic_vector(0 downto 0);
        tx_axis_mac_tlast  : in  std_logic;
        tx_axis_mac_tuser  : in  std_logic;
        tx_axis_mac_tready : out std_logic;
        s_axi_aclk         : in  std_logic;
        s_axi_awaddr       : in  std_logic_vector(9 downto 0);
        s_axi_awvalid      : in  std_logic;
        s_axi_awready      : out std_logic;
        s_axi_wdata        : in  std_logic_vector(31 downto 0);
        s_axi_wvalid       : in  std_logic;
        s_axi_wready       : out std_logic;
        s_axi_bresp        : out std_logic_vector(1 downto 0);
        s_axi_bvalid       : out std_logic;
        s_axi_bready       : in  std_logic;
        s_axi_araddr       : in  std_logic_vector(9 downto 0);
        s_axi_arvalid      : in  std_logic;
        s_axi_arready      : out std_logic;
        s_axi_rresp        : out std_logic_vector(1 downto 0);
        s_axi_rdata        : out std_logic_vector(31 downto 0);
        s_axi_rvalid       : out std_logic;
        s_axi_rready       : in  std_logic;
        rgmii_txd_HI       : out std_logic_vector(3 downto 0);
        rgmii_txd_LO       : out std_logic_vector(3 downto 0);
        rgmii_tx_ctl_HI    : out std_logic;
        rgmii_tx_ctl_LO    : out std_logic;
        rgmii_txc_HI       : out std_logic;
        rgmii_txc_LO       : out std_logic;
        rgmii_rxd_HI       : in  std_logic_vector(3 downto 0);
        rgmii_rxd_LO       : in  std_logic_vector(3 downto 0);
        rgmii_rx_ctl_HI    : in  std_logic;
        rgmii_rx_ctl_LO    : in  std_logic;
        rgmii_rxc          : in  std_logic;
        Mdo                : out std_logic;
        MdoEn              : out std_logic;
        Mdi                : in  std_logic;
        Mdc                : out std_logic
    );
    end component efx_tsemac;

    component apb3_2_axi4_lite is
    port(
        clk              : in  std_logic;
        rstn             : in  std_logic;
        s_apb3_paddr     : in  std_logic_vector(9 downto 0);
        s_apb3_psel      : in  std_logic;
        s_apb3_penable   : in  std_logic;
        s_apb3_pwrite    : in  std_logic;
        s_apb3_pwdata    : in  std_logic_vector(31 downto 0);
        s_apb3_pready    : out std_logic;
        s_apb3_prdata    : out std_logic_vector(31 downto 0);
        s_apb3_pslverror : out std_logic;
        m_axi_awaddr     : out std_logic_vector(9 downto 0);
        m_axi_awvalid    : out std_logic;
        m_axi_awready    : in  std_logic;
        m_axi_wdata      : out std_logic_vector(31 downto 0);
        m_axi_wvalid     : out std_logic;
        m_axi_wready     : in  std_logic;
        m_axi_araddr     : out std_logic_vector(9 downto 0);
        m_axi_arvalid    : out std_logic;
        m_axi_arready    : in  std_logic;
        m_axi_rdata      : in  std_logic_vector(31 downto 0);
        m_axi_rvalid     : in  std_logic;
        m_axi_rready     : out std_logic
    );
    end component apb3_2_axi4_lite;

    -- a reset into a clock domain: on at once, off two clocks after its source
    signal mac_reset_sync, proto_reset_sync, tx_reset_sync : std_logic_vector(1 downto 0) := (others => '1');
    attribute async_reg : string;
    attribute async_reg of mac_reset_sync, proto_reset_sync, tx_reset_sync : signal is "true";

    signal pll_reset : std_logic;
    signal sw_mac_reset, sw_dma_rx_reset, sw_dma_tx_reset : std_logic;
    signal mac_reset, proto_reset, tx_path_reset, rx_dma_reset, tx_dma_reset : std_logic;
    signal bridge_resetn : std_logic;

    -- the register window: the MAC's below 0x200, the control's above
    signal control_selected : boolean;
    signal mac_psel, control_psel : std_logic;
    signal mac_pready, mac_pslverror, control_pready, control_pslverror : std_logic;
    signal mac_prdata, control_prdata : std_logic_vector(31 downto 0);

    signal axil_awaddr, axil_araddr : std_logic_vector(9 downto 0);
    signal axil_awvalid, axil_awready, axil_wvalid, axil_wready : std_logic;
    signal axil_arvalid, axil_arready, axil_rvalid, axil_rready : std_logic;
    signal axil_wdata, axil_rdata : std_logic_vector(31 downto 0);

    -- the streams: receive MAC -> DMA, transmit DMA -> inserter -> MAC
    signal rx_tvalid, rx_tready, rx_tlast : std_logic;
    signal rx_tdata : std_logic_vector(7 downto 0);
    signal dma_tx_tvalid, dma_tx_tready, dma_tx_tlast : std_logic;
    signal dma_tx_tdata : std_logic_vector(7 downto 0);
    signal dma_tx_tkeep : std_logic_vector(0 downto 0);
    signal dma_tx_tdest : std_logic_vector(3 downto 0);
    signal mac_tx_tvalid, mac_tx_tready, mac_tx_tlast : std_logic;
    signal mac_tx_tdata : std_logic_vector(7 downto 0);

begin

    pll_reset <= not pll_locked;

    -- the resets into the MAC's clock domain (its transmit clock, io_tseClk)
    process(io_tseClk, pll_reset)
    begin
        if pll_reset = '1' then
            mac_reset_sync <= (others => '1');
        elsif rising_edge(io_tseClk) then
            mac_reset_sync <= mac_reset_sync(0) & '0';
        end if;
    end process;

    process(io_tseClk, sw_mac_reset)
    begin
        if sw_mac_reset = '1' then
            proto_reset_sync <= (others => '1');
        elsif rising_edge(io_tseClk) then
            proto_reset_sync <= proto_reset_sync(0) & '0';
        end if;
    end process;

    process(io_tseClk, pll_reset, sw_dma_tx_reset)
    begin
        if pll_reset = '1' or sw_dma_tx_reset = '1' then
            tx_reset_sync <= (others => '1');
        elsif rising_edge(io_tseClk) then
            tx_reset_sync <= tx_reset_sync(0) & '0';
        end if;
    end process;

    mac_reset     <= mac_reset_sync(1);
    proto_reset   <= mac_reset_sync(1) or proto_reset_sync(1);
    tx_path_reset <= tx_reset_sync(1);
    -- the DMA's stream ports take their resets as they come (it synchronises them itself)
    rx_dma_reset  <= pll_reset or sw_dma_rx_reset;
    tx_dma_reset  <= pll_reset or sw_dma_tx_reset;
    bridge_resetn <= not (io_systemReset or sw_mac_reset);

    -- the register window
    control_selected   <= eth_apb3_paddr(9) = '1';
    mac_psel           <= eth_apb3_psel when not control_selected else '0';
    control_psel       <= eth_apb3_psel when control_selected else '0';
    eth_apb3_pready    <= control_pready    when control_selected else mac_pready;
    eth_apb3_prdata    <= control_prdata    when control_selected else mac_prdata;
    eth_apb3_pslverror <= control_pslverror when control_selected else mac_pslverror;

    u_control : entity work.tsemac_control
    port map(
        clock        => io_peripheralClk
        ,reset       => io_systemReset
        ,paddr       => eth_apb3_paddr(8 downto 0)
        ,psel        => control_psel
        ,penable     => eth_apb3_penable
        ,pwrite      => eth_apb3_pwrite
        ,pwdata      => eth_apb3_pwdata
        ,pready      => control_pready
        ,prdata      => control_prdata
        ,pslverror   => control_pslverror
        ,mac_reset   => sw_mac_reset
        ,phy_reset   => phy_sw_rst
        ,dma_rx_reset => sw_dma_rx_reset
        ,dma_tx_reset => sw_dma_tx_reset
    );

    u_bridge : apb3_2_axi4_lite
    port map(
        clk               => io_peripheralClk
        ,rstn             => bridge_resetn
        ,s_apb3_paddr     => '0' & eth_apb3_paddr(8 downto 0)
        ,s_apb3_psel      => mac_psel
        ,s_apb3_penable   => eth_apb3_penable
        ,s_apb3_pwrite    => eth_apb3_pwrite
        ,s_apb3_pwdata    => eth_apb3_pwdata
        ,s_apb3_pready    => mac_pready
        ,s_apb3_prdata    => mac_prdata
        ,s_apb3_pslverror => mac_pslverror
        ,m_axi_awaddr     => axil_awaddr
        ,m_axi_awvalid    => axil_awvalid
        ,m_axi_awready    => axil_awready
        ,m_axi_wdata      => axil_wdata
        ,m_axi_wvalid     => axil_wvalid
        ,m_axi_wready     => axil_wready
        ,m_axi_araddr     => axil_araddr
        ,m_axi_arvalid    => axil_arvalid
        ,m_axi_arready    => axil_arready
        ,m_axi_rdata      => axil_rdata
        ,m_axi_rvalid     => axil_rvalid
        ,m_axi_rready     => axil_rready
    );

    u_dma : dma
    port map(
        clk             => io_memoryClk
        ,reset          => io_ddrMasterReset
        ,ctrl_clk       => io_peripheralClk
        ,ctrl_reset     => io_systemReset
        ,ctrl_PADDR     => dma_apb3_paddr(13 downto 0)
        ,ctrl_PREADY    => dma_apb3_pready
        ,ctrl_PENABLE   => dma_apb3_penable
        ,ctrl_PSEL      => dma_apb3_psel
        ,ctrl_PWRITE    => dma_apb3_pwrite
        ,ctrl_PWDATA    => dma_apb3_pwdata
        ,ctrl_PRDATA    => dma_apb3_prdata
        ,ctrl_PSLVERROR => dma_apb3_pslverror
        ,ctrl_interrupts => dma_interrupts
        ,read_arvalid   => dmaaxi_read_arvalid
        ,read_araddr    => dmaaxi_read_araddr
        ,read_arready   => dmaaxi_read_arready
        ,read_arregion  => dmaaxi_read_arregion
        ,read_arlen     => dmaaxi_read_arlen
        ,read_arsize    => dmaaxi_read_arsize
        ,read_arburst   => dmaaxi_read_arburst
        ,read_arlock    => dmaaxi_read_arlock(0)
        ,read_arcache   => dmaaxi_read_arcache
        ,read_arqos     => dmaaxi_read_arqos
        ,read_arprot    => dmaaxi_read_arprot
        ,read_rready    => dmaaxi_read_rready
        ,read_rvalid    => dmaaxi_read_rvalid
        ,read_rdata     => dmaaxi_read_rdata
        ,read_rlast     => dmaaxi_read_rlast
        ,read_rresp     => dmaaxi_read_rresp
        ,write_awvalid  => dmaaxi_write_awvalid
        ,write_awready  => dmaaxi_write_awready
        ,write_awaddr   => dmaaxi_write_awaddr
        ,write_awregion => dmaaxi_write_awregion
        ,write_awlen    => dmaaxi_write_awlen
        ,write_awsize   => dmaaxi_write_awsize
        ,write_awburst  => dmaaxi_write_awburst
        ,write_awlock   => dmaaxi_write_awlock(0)
        ,write_awcache  => dmaaxi_write_awcache
        ,write_awqos    => dmaaxi_write_awqos
        ,write_awprot   => dmaaxi_write_awprot
        ,write_wvalid   => dmaaxi_write_wvalid
        ,write_wready   => dmaaxi_write_wready
        ,write_wdata    => dmaaxi_write_wdata
        ,write_wstrb    => dmaaxi_write_wstrb
        ,write_wlast    => dmaaxi_write_wlast
        ,write_bvalid   => dmaaxi_write_bvalid
        ,write_bready   => dmaaxi_write_bready
        ,write_bresp    => dmaaxi_write_bresp
        ,io_0_descriptorUpdate => open
        ,io_1_descriptorUpdate => open
        -- channel 0: received frames into memory
        ,dat0_i_clk     => rgmii_rxc
        ,dat0_i_reset   => rx_dma_reset
        ,dat0_i_tvalid  => rx_tvalid
        ,dat0_i_tready  => rx_tready
        ,dat0_i_tdata   => rx_tdata
        ,dat0_i_tkeep   => "1"
        ,dat0_i_tdest   => "0000"
        ,dat0_i_tlast   => rx_tlast
        -- channel 1: frames to transmit out of memory
        ,dat1_o_clk     => io_tseClk
        ,dat1_o_reset   => tx_dma_reset
        ,dat1_o_tvalid  => dma_tx_tvalid
        ,dat1_o_tready  => dma_tx_tready
        ,dat1_o_tdata   => dma_tx_tdata
        ,dat1_o_tkeep   => dma_tx_tkeep
        ,dat1_o_tdest   => dma_tx_tdest
        ,dat1_o_tlast   => dma_tx_tlast
    );

    u_tx_checksum_inserter : entity work.tx_checksum_inserter
    port map(
        clock     => io_tseClk
        ,reset    => tx_path_reset
        ,s_tvalid => dma_tx_tvalid
        ,s_tready => dma_tx_tready
        ,s_tdata  => dma_tx_tdata
        ,s_tkeep  => dma_tx_tkeep(0)
        ,s_tdest  => dma_tx_tdest
        ,s_tlast  => dma_tx_tlast
